namespace ghidra.app.plugin.core.compositeeditor;

using docking;
using ghidra.program.model.data;
using ghidra.program.model.data;

/**
 * Action for use in the composite data type editor.
 * This action has help associated with it.
 */
public class ShowComponentPathAction : CompositeEditorTableAction {

	public static string ACTION_NAME = "Show Component Path";
	private static string GROUP_NAME = BASIC_ACTION_GROUP;
	private static string DESCRIPTION =
		"Show the category for the selected component's data type";
	private static string[] POPUP_PATH = new string[] { ACTION_NAME };
	private static string[] MENU_PATH = new string[] { ACTION_NAME };

	public ShowComponentPathAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, MENU_PATH, null)
    {
		setDescription(DESCRIPTION);
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		if (!isEnabledForContext(context)) {
			return;
		}
		string message = " ";
		int index = model.getMinIndexSelected();
		DataTypeComponent dtc = model.getComponent(index);
		if (dtc != null) {
			DataType dt = dtc.getDataType();
			message =
				dt.getDisplayName() + " is in category \"" + dt.getCategoryPath().getPath() + "\".";

		}
		model.setStatus(message, false);
		requestTableFocus();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() && model.isSingleComponentRowSelection();
	}
}
